-- Generated by scripts/build-player-guide-seed.mts on 8 October 2026.
-- Brings the support FAQ and the team's player guides up to the released iOS 5.1.1 (Slide &
-- Match), checked against Apple's lookup and the App Store description the same day:
--   * FAQ: up to 39 rewarded videos a day across eight placements (the seed said 31 across six;
--     20261007160000 listed the caps but not the total, and never reached pt-BR); a life is
--     also lost by restarting after a move; pt-BR timer and stars answers match the site.
--   * Guides: "Checked … released iOS 5.1.1", and slide-and-match steps in place of the 5.0.1
--     match-three swap steps; the version guide's "in development" 5.1 note becomes "New in 5.1".
-- Each row changes only while it still holds text an earlier migration seeded, so a team edit
-- made in the community is never overwritten. No notifications; idempotent on replay.

-- Support FAQ ---------------------------------------------------------------------------
UPDATE faq_entries SET answer_md = 'Opening a board needs a life but spends none. Clearing spends none. A life goes when you decline the out-of-moves continue, leave after making a move, or restart after making a move. Five lives, eight with Brick Pass; one refills every thirty minutes.', answer_html = '<p>Opening a board needs a life but spends none. Clearing spends none. A life goes when you decline the out-of-moves continue, leave after making a move, or restart after making a move. Five lives, eight with Brick Pass; one refills every thirty minutes.</p>', updated_at = now()
 WHERE locale = 'en' AND position = 1 AND topic = 'lives' AND answer_md IN ('Five, or eight while you hold the Brick Pass, and one comes back every thirty minutes. A life is spent only when you run out of moves and choose Try again, or leave a board you have already made a move on.');
UPDATE faq_entries SET answer_md = 'The board shows moves remaining; there is no clock or countdown. At the limit, five extra moves cost 300 coins, then 500, then 900 within the same attempt, or a rewarded video. Leaving or clearing resets the coin ladder.', answer_html = '<p>The board shows moves remaining; there is no clock or countdown. At the limit, five extra moves cost 300 coins, then 500, then 900 within the same attempt, or a rewarded video. Leaving or clearing resets the coin ladder.</p>', updated_at = now()
 WHERE locale = 'en' AND position = 3 AND topic = 'moves' AND answer_md IN ('No. Every board has a move limit, shown beside your move count from the first tap, but there is no clock or countdown. Reaching the limit offers five more moves for coins or a video before anything else happens.');
UPDATE faq_entries SET answer_md = 'The current iOS game awards stars from the board’s score thresholds. Matches, specials, cascades and the leftover-move finish contribute to the score. The browser demo keeps its earlier move-target star rule.', answer_html = '<p>The current iOS game awards stars from the board’s score thresholds. Matches, specials, cascades and the leftover-move finish contribute to the score. The browser demo keeps its earlier move-target star rule.</p>', updated_at = now()
 WHERE locale = 'en' AND position = 5 AND topic = 'stars' AND answer_md IN ('One star for clearing the board, the second for clearing it at or under the target move count, and the third for doing that without an undo. The target used to be called par; it is the same number.');
UPDATE faq_entries SET answer_md = 'Eight opt-in video placements, capped at 39 a day. Daily caps: lives 8, undos 8, extra moves 6, a free Hint at the out-of-moves wall 4, doubled clear coins 4, Brick Wheel 1, the gift balloon 2 and Brick Cinema 6. No banners or interstitials. A video starts only when you choose it; declining costs nothing.', answer_html = '<p>Eight opt-in video placements, capped at 39 a day. Daily caps: lives 8, undos 8, extra moves 6, a free Hint at the out-of-moves wall 4, doubled clear coins 4, Brick Wheel 1, the gift balloon 2 and Brick Cinema 6. No banners or interstitials. A video starts only when you choose it; declining costs nothing.</p>', updated_at = now()
 WHERE locale = 'en' AND position = 7 AND topic = 'ads' AND answer_md IN ('Thirty-one at most across the six rewards, each capped daily. Declining never changes a reward, a board or a price.', 'Daily caps: lives 8, undos 8, extra moves 6, a free Hint at the out-of-moves wall 4, doubled clear coins 4, Brick Wheel 1, the gift balloon 2 and Brick Cinema 6. No banners or interstitials. A video starts only when you choose it; declining costs nothing.');
UPDATE faq_entries SET answer_md = 'Ouvrir un plateau demande une vie sans en consommer. Le terminer n’en consomme pas. Une vie part si vous refusez de continuer sans coups, quittez après un coup ou recommencez après un coup. Cinq vies, huit avec Brick Pass ; une revient toutes les trente minutes.', answer_html = '<p>Ouvrir un plateau demande une vie sans en consommer. Le terminer n’en consomme pas. Une vie part si vous refusez de continuer sans coups, quittez après un coup ou recommencez après un coup. Cinq vies, huit avec Brick Pass ; une revient toutes les trente minutes.</p>', updated_at = now()
 WHERE locale = 'fr' AND position = 1 AND topic = 'lives' AND answer_md IN ('Cinq, huit avec le Brick Pass ; une revient toutes les trente minutes. Une vie est dépensée uniquement si vous manquez de coups et choisissez Réessayer, ou quittez un plateau où vous avez déjà joué.');
UPDATE faq_entries SET answer_md = 'Le plateau affiche les coups restants, sans chrono. À la limite, cinq coups supplémentaires coûtent 300 pièces, puis 500, puis 900 dans la même tentative, ou une vidéo récompensée. Quitter ou terminer le plateau remet le tarif à zéro.', answer_html = '<p>Le plateau affiche les coups restants, sans chrono. À la limite, cinq coups supplémentaires coûtent 300 pièces, puis 500, puis 900 dans la même tentative, ou une vidéo récompensée. Quitter ou terminer le plateau remet le tarif à zéro.</p>', updated_at = now()
 WHERE locale = 'fr' AND position = 3 AND topic = 'moves' AND answer_md IN ('Non. Chaque plateau affiche une limite de coups près du compteur dès le premier toucher, sans horloge ni compte à rebours. À la limite, cinq coups supplémentaires sont proposés contre pièces ou vidéo avant toute autre action.');
UPDATE faq_entries SET answer_md = 'Sur iOS, les étoiles dépendent des seuils de score du plateau. Alignements, spéciaux, cascades et coups restants contribuent au score. La démo web conserve son ancienne règle d’étoiles selon les coups.', answer_html = '<p>Sur iOS, les étoiles dépendent des seuils de score du plateau. Alignements, spéciaux, cascades et coups restants contribuent au score. La démo web conserve son ancienne règle d’étoiles selon les coups.</p>', updated_at = now()
 WHERE locale = 'fr' AND position = 5 AND topic = 'stars' AND answer_md IN ('Une pour terminer, la deuxième à l’objectif ou en dessous, la troisième pour le faire sans annulation. L’objectif s’appelait auparavant par : c’est le même nombre.');
UPDATE faq_entries SET answer_md = 'Huit vidéos facultatives, au plus 39 par jour. Plafonds quotidiens : vies 8, annulations 8, coups supplémentaires 6, indice gratuit à la limite des coups 4, pièces de victoire doublées 4, Brick Wheel 1, ballon cadeau 2 et Brick Cinema 6. Ni bannières ni publicités imposées. Une vidéo ne démarre que si vous la choisissez ; refuser ne coûte rien.', answer_html = '<p>Huit vidéos facultatives, au plus 39 par jour. Plafonds quotidiens : vies 8, annulations 8, coups supplémentaires 6, indice gratuit à la limite des coups 4, pièces de victoire doublées 4, Brick Wheel 1, ballon cadeau 2 et Brick Cinema 6. Ni bannières ni publicités imposées. Une vidéo ne démarre que si vous la choisissez ; refuser ne coûte rien.</p>', updated_at = now()
 WHERE locale = 'fr' AND position = 7 AND topic = 'ads' AND answer_md IN ('Au plus trente et une, réparties sur six récompenses plafonnées chaque jour. Refuser ne change jamais récompense, plateau ou prix.', 'Plafonds quotidiens : vies 8, annulations 8, coups supplémentaires 6, indice gratuit à la limite des coups 4, pièces de victoire doublées 4, Brick Wheel 1, ballon cadeau 2 et Brick Cinema 6. Ni bannières ni publicités imposées. Une vidéo ne démarre que si vous la choisissez ; refuser ne coûte rien.');
UPDATE faq_entries SET answer_md = 'Ein Feld öffnen erfordert ein Leben, verbraucht aber keines. Lösen kostet keines. Ein Leben geht verloren, wenn du am Zuglimit nicht fortsetzt, nach einem Zug gehst oder nach einem Zug neu startest. Fünf Leben, acht mit Brick Pass; eines kommt alle dreißig Minuten zurück.', answer_html = '<p>Ein Feld öffnen erfordert ein Leben, verbraucht aber keines. Lösen kostet keines. Ein Leben geht verloren, wenn du am Zuglimit nicht fortsetzt, nach einem Zug gehst oder nach einem Zug neu startest. Fünf Leben, acht mit Brick Pass; eines kommt alle dreißig Minuten zurück.</p>', updated_at = now()
 WHERE locale = 'de' AND position = 1 AND topic = 'lives' AND answer_md IN ('Fünf oder acht mit Brick Pass; alle dreißig Minuten kommt eines zurück. Ein Leben wird nur verbraucht, wenn du keine Züge mehr hast und ‚Erneut versuchen‘ wählst oder ein Feld verlässt, auf dem du bereits gezogen hast.');
UPDATE faq_entries SET answer_md = 'Das Feld zeigt die übrigen Züge; es gibt keinen Timer. Am Limit kosten fünf Extrazüge 300, dann 500, dann 900 Münzen im selben Versuch oder ein Belohnungsvideo. Verlassen oder Lösen setzt die Preisleiter zurück.', answer_html = '<p>Das Feld zeigt die übrigen Züge; es gibt keinen Timer. Am Limit kosten fünf Extrazüge 300, dann 500, dann 900 Münzen im selben Versuch oder ein Belohnungsvideo. Verlassen oder Lösen setzt die Preisleiter zurück.</p>', updated_at = now()
 WHERE locale = 'de' AND position = 3 AND topic = 'moves' AND answer_md IN ('Nein. Jedes Feld zeigt ab dem ersten Tippen ein Zuglimit neben dem Zugzähler, aber keine Uhr oder keinen Countdown. Beim Erreichen werden zuerst fünf weitere Züge für Münzen oder ein Video angeboten.');
UPDATE faq_entries SET answer_md = 'In der aktuellen iOS-App richten sich Sterne nach den Punktschwellen des Feldes. Kombinationen, Spezialsteine, Kaskaden und übrige Züge tragen dazu bei. Die Webdemo behält ihre frühere Zugvorgabenregel.', answer_html = '<p>In der aktuellen iOS-App richten sich Sterne nach den Punktschwellen des Feldes. Kombinationen, Spezialsteine, Kaskaden und übrige Züge tragen dazu bei. Die Webdemo behält ihre frühere Zugvorgabenregel.</p>', updated_at = now()
 WHERE locale = 'de' AND position = 5 AND topic = 'stars' AND answer_md IN ('Ein Stern fürs Lösen, der zweite fürs Lösen innerhalb oder unterhalb der Zugvorgabe und der dritte dafür ohne Zugrücknahme. Die Vorgabe hieß früher Par; es ist dieselbe Zahl.');
UPDATE faq_entries SET answer_md = 'Acht freiwillige Videoplatzierungen, höchstens 39 täglich. Tageslimits: Leben 8, Rückgängig 8, Extrazüge 6, kostenloser Hinweis am Zuglimit 4, doppelte Münzen 4, Brick Wheel 1, Geschenkballon 2 und Brick Cinema 6. Keine Banner oder Zwischenwerbung. Videos starten nur auf Wunsch; Ablehnen kostet nichts.', answer_html = '<p>Acht freiwillige Videoplatzierungen, höchstens 39 täglich. Tageslimits: Leben 8, Rückgängig 8, Extrazüge 6, kostenloser Hinweis am Zuglimit 4, doppelte Münzen 4, Brick Wheel 1, Geschenkballon 2 und Brick Cinema 6. Keine Banner oder Zwischenwerbung. Videos starten nur auf Wunsch; Ablehnen kostet nichts.</p>', updated_at = now()
 WHERE locale = 'de' AND position = 7 AND topic = 'ads' AND answer_md IN ('Höchstens einunddreißig über sechs Belohnungen, jede täglich begrenzt. Ablehnen verändert weder Belohnung noch Feld oder Preis.', 'Tageslimits: Leben 8, Rückgängig 8, Extrazüge 6, kostenloser Hinweis am Zuglimit 4, doppelte Münzen 4, Brick Wheel 1, Geschenkballon 2 und Brick Cinema 6. Keine Banner oder Zwischenwerbung. Videos starten nur auf Wunsch; Ablehnen kostet nichts.');
UPDATE faq_entries SET answer_md = 'Abrir un tablero requiere una vida pero no la gasta. Completarlo tampoco. Se pierde al rechazar continuar sin movimientos, salir tras mover o reiniciar después de mover. Cinco vidas, ocho con Brick Pass; recuperas una cada treinta minutos.', answer_html = '<p>Abrir un tablero requiere una vida pero no la gasta. Completarlo tampoco. Se pierde al rechazar continuar sin movimientos, salir tras mover o reiniciar después de mover. Cinco vidas, ocho con Brick Pass; recuperas una cada treinta minutos.</p>', updated_at = now()
 WHERE locale = 'es' AND position = 1 AND topic = 'lives' AND answer_md IN ('Cinco, u ocho mientras tengas Brick Pass, y recuperas una cada treinta minutos. Solo consumes una al quedarte sin movimientos y elegir Reintentar, o al dejar un tablero donde ya has movido.');
UPDATE faq_entries SET answer_md = 'El tablero muestra movimientos restantes, sin temporizador. Al agotarlos, cinco más cuestan 300 monedas, luego 500 y luego 900 dentro del mismo intento, o un vídeo con recompensa. Salir o completar reinicia la escala.', answer_html = '<p>El tablero muestra movimientos restantes, sin temporizador. Al agotarlos, cinco más cuestan 300 monedas, luego 500 y luego 900 dentro del mismo intento, o un vídeo con recompensa. Salir o completar reinicia la escala.</p>', updated_at = now()
 WHERE locale = 'es' AND position = 3 AND topic = 'moves' AND answer_md IN ('No. Cada tablero tiene un límite de movimientos junto al contador desde el primer toque, pero ningún reloj ni cuenta atrás. Al alcanzarlo se ofrecen cinco movimientos más por monedas o un vídeo antes de que ocurra nada más.');
UPDATE faq_entries SET answer_md = 'En iOS, las estrellas dependen de los umbrales de puntuación del tablero. Combinaciones, especiales, cascadas y movimientos restantes contribuyen al total. La demo web conserva su antigua regla por movimientos.', answer_html = '<p>En iOS, las estrellas dependen de los umbrales de puntuación del tablero. Combinaciones, especiales, cascadas y movimientos restantes contribuyen al total. La demo web conserva su antigua regla por movimientos.</p>', updated_at = now()
 WHERE locale = 'es' AND position = 5 AND topic = 'stars' AND answer_md IN ('Una por despejar, la segunda por hacerlo en el objetivo o menos movimientos y la tercera por hacerlo sin deshacer. El objetivo antes se llamaba par; es el mismo número.');
UPDATE faq_entries SET answer_md = 'Ocho vídeos opcionales, hasta 39 al día. Límites diarios: vidas 8, deshacer 8, movimientos extra 6, pista gratis al agotar movimientos 4, monedas duplicadas 4, Brick Wheel 1, globo de regalo 2 y Brick Cinema 6. Sin banners ni anuncios intermedios. Un vídeo solo empieza si lo eliges; rechazarlo no cuesta nada.', answer_html = '<p>Ocho vídeos opcionales, hasta 39 al día. Límites diarios: vidas 8, deshacer 8, movimientos extra 6, pista gratis al agotar movimientos 4, monedas duplicadas 4, Brick Wheel 1, globo de regalo 2 y Brick Cinema 6. Sin banners ni anuncios intermedios. Un vídeo solo empieza si lo eliges; rechazarlo no cuesta nada.</p>', updated_at = now()
