UPDATE faq_entries SET answer_md = '盤面を開くにはライフが必要ですが消費しません。クリアでも消費しません。手数切れで続行を断る、1手動かした後に退出する、動かした後に再開する場合に1つ失います。ライフは5、Brick Passでは8。30分に1つ回復します。', answer_html = '<p>盤面を開くにはライフが必要ですが消費しません。クリアでも消費しません。手数切れで続行を断る、1手動かした後に退出する、動かした後に再開する場合に1つ失います。ライフは5、Brick Passでは8。30分に1つ回復します。</p>', updated_at = now()
 WHERE locale = 'ja' AND position = 1 AND topic = 'lives' AND answer_md IN ('5つ、Brick Pass保有中は8つで、30分ごとに1つ回復。手数切れで再挑戦を選ぶか、すでに動かした盤面を離れる場合だけ使います。');
UPDATE faq_entries SET answer_md = '盤面には残り手数を表示し、時計やタイマーはありません。手数切れでは5手追加が同じ挑戦中に300、500、900コインと上がるか、報酬動画を選べます。退出やクリアで価格はリセットされます。', answer_html = '<p>盤面には残り手数を表示し、時計やタイマーはありません。手数切れでは5手追加が同じ挑戦中に300、500、900コインと上がるか、報酬動画を選べます。退出やクリアで価格はリセットされます。</p>', updated_at = now()
