UPDATE faq_entries SET answer_md = '現在のiOSゲームでは盤面のスコア基準で星を獲得します。マッチ、特殊ブロック、連鎖、残り手数のフィニッシュがスコアに加わります。ウェブデモは以前の手数目標による星のルールを残しています。', answer_html = '<p>現在のiOSゲームでは盤面のスコア基準で星を獲得します。マッチ、特殊ブロック、連鎖、残り手数のフィニッシュがスコアに加わります。ウェブデモは以前の手数目標による星のルールを残しています。</p>', updated_at = now()
 WHERE locale = 'ja' AND position = 5 AND topic = 'stars' AND answer_md IN ('クリアで1、目標手数以下で2、さらにアンドゥなしで3です。目標は以前パーと呼んでいましたが同じ数字です。');
UPDATE faq_entries SET answer_md = '任意の動画は8種類、1日最大39回。1日の上限：ライフ8、取り消し8、追加手数6、手数切れ画面の無料ヒント4、クリア時のコイン倍増4、Brick Wheel 1、ギフト風船2、Brick Cinema 6。バナーや強制広告はありません。選んだときだけ再生し、断っても不利益はありません。', answer_html = '<p>任意の動画は8種類、1日最大39回。1日の上限：ライフ8、取り消し8、追加手数6、手数切れ画面の無料ヒント4、クリア時のコイン倍増4、Brick Wheel 1、ギフト風船2、Brick Cinema 6。バナーや強制広告はありません。選んだときだけ再生し、断っても不利益はありません。</p>', updated_at = now()
 WHERE locale = 'ja' AND position = 7 AND topic = 'ads' AND answer_md IN ('六つの報酬全体で最大31本、各々1日上限があります。断っても報酬、盤面、価格は変わりません。', '1日の上限：ライフ8、取り消し8、追加手数6、手数切れ画面の無料ヒント4、クリア時のコイン倍増4、Brick Wheel 1、ギフト風船2、Brick Cinema 6。バナーや強制広告はありません。選んだときだけ再生し、断っても不利益はありません。');
UPDATE faq_entries SET answer_md = 'Abrir uma fase exige uma vida, mas não consome nenhuma. Concluir também não consome. Uma vida é usada quando você recusa continuar sem jogadas, sai depois de fazer uma jogada ou reinicia depois de jogar. São cinco vidas, oito com o Brick Pass; uma se recupera a cada trinta minutos.', answer_html = '<p>Abrir uma fase exige uma vida, mas não consome nenhuma. Concluir também não consome. Uma vida é usada quando você recusa continuar sem jogadas, sai depois de fazer uma jogada ou reinicia depois de jogar. São cinco vidas, oito com o Brick Pass; uma se recupera a cada trinta minutos.</p>', updated_at = now()
