UPDATE faq_entries SET answer_md = 'A fase mostra as jogadas restantes; não há relógio nem contagem regressiva. Ao atingir o limite, cinco jogadas extras custam 300 moedas, depois 500 e então 900 na mesma tentativa, ou podem ser obtidas com um vídeo com recompensa. Sair ou concluir a fase reinicia essa sequência de preços.', answer_html = '<p>A fase mostra as jogadas restantes; não há relógio nem contagem regressiva. Ao atingir o limite, cinco jogadas extras custam 300 moedas, depois 500 e então 900 na mesma tentativa, ou podem ser obtidas com um vídeo com recompensa. Sair ou concluir a fase reinicia essa sequência de preços.</p>', updated_at = now()
 WHERE locale = 'pt-BR' AND position = 3 AND topic = 'moves' AND answer_md IN ('Não. Cada fase tem um limite de movimentos, exibido ao lado do contador desde o primeiro toque, mas não há relógio nem contagem regressiva. Ao chegar ao limite, você pode escolher cinco movimentos extras em troca de moedas ou de um vídeo antes que qualquer outra coisa aconteça.');
UPDATE faq_entries SET answer_md = 'O jogo atual para iOS concede estrelas de acordo com as faixas de pontuação da fase. Combinações, especiais, cascatas e jogadas restantes contribuem para a pontuação. A demonstração no navegador mantém a antiga regra de estrelas baseada no objetivo de jogadas.', answer_html = '<p>O jogo atual para iOS concede estrelas de acordo com as faixas de pontuação da fase. Combinações, especiais, cascatas e jogadas restantes contribuem para a pontuação. A demonstração no navegador mantém a antiga regra de estrelas baseada no objetivo de jogadas.</p>', updated_at = now()
