<ul><li><a href="/community/guide-placeholder/first-board" rel="ugc nofollow noopener">Premiers pas : jouer un tableau</a></li><li><a href="/community/guide-placeholder/specials-and-stars" rel="ugc nofollow noopener">Briques spéciales, objectifs et étoiles</a></li><li><a href="/community/guide-placeholder/journey" rel="ugc nofollow noopener">Se repérer dans le Voyage</a></li><li><a href="/community/guide-placeholder/settings" rel="ugc nofollow noopener">Accessibilité et réglages confortables</a></li><li><a href="/community/guide-placeholder/lives-moves-undos" rel="ugc nofollow noopener">Vies, coups, annulations et vidéos facultatives</a></li><li><a href="/community/guide-placeholder/asking-for-help" rel="ugc nofollow noopener">Demander de l’aide et signaler un problème d’accessibilité</a></li><li><a href="/community/guide-placeholder/versions" rel="ugc nofollow noopener">À quelle version est-ce que je joue ?</a></li></ul>';
BEGIN
 SELECT thread_id INTO tid FROM player_guides WHERE locale = 'fr' AND key = 'voiceover';
 IF tid IS NULL THEN RETURN; END IF;
 FOR target IN SELECT g.key, t.id, t.slug FROM player_guides g JOIN threads t ON t.id = g.thread_id WHERE g.locale = 'fr' LOOP
  old_md := replace(old_md, '/community/guide-placeholder/' || target.key, '/fr/community/t/' || target.id || '/' || target.slug);
  new_md := replace(new_md, '/community/guide-placeholder/' || target.key, '/fr/community/t/' || target.id || '/' || target.slug);
