<h3>あわせて読む</h3>
<p><a href="/community/guide-placeholder/index" rel="ugc nofollow noopener">OutBrickプレイヤーガイド集</a></p>
<ul><li><a href="/community/guide-placeholder/first-board" rel="ugc nofollow noopener">はじめに：最初の盤面を遊ぶ</a></li><li><a href="/community/guide-placeholder/specials-and-stars" rel="ugc nofollow noopener">特殊ブロック・目標・スコアの星</a></li><li><a href="/community/guide-placeholder/journey" rel="ugc nofollow noopener">Journeyの歩き方</a></li><li><a href="/community/guide-placeholder/settings" rel="ugc nofollow noopener">アクセシビリティと快適な設定</a></li><li><a href="/community/guide-placeholder/lives-moves-undos" rel="ugc nofollow noopener">ライフ・手数・取り消し・任意の動画</a></li><li><a href="/community/guide-placeholder/asking-for-help" rel="ugc nofollow noopener">質問とアクセシビリティ問題の報告</a></li><li><a href="/community/guide-placeholder/versions" rel="ugc nofollow noopener">どのバージョンを遊んでいますか？</a></li></ul>';
BEGIN
 SELECT thread_id INTO tid FROM player_guides WHERE locale = 'ja' AND key = 'voiceover';
 IF tid IS NULL THEN RETURN; END IF;
 FOR target IN SELECT g.key, t.id, t.slug FROM player_guides g JOIN threads t ON t.id = g.thread_id WHERE g.locale = 'ja' LOOP
  old_md := replace(old_md, '/community/guide-placeholder/' || target.key, '/ja/community/t/' || target.id || '/' || target.slug);
  new_md := replace(new_md, '/community/guide-placeholder/' || target.key, '/ja/community/t/' || target.id || '/' || target.slug);
  new_html := replace(new_html, '/community/guide-placeholder/' || target.key, '/ja/community/t/' || target.id || '/' || target.slug);
 END LOOP;
 UPDATE posts SET body_md = new_md, body_html = new_html WHERE thread_id = tid AND number = 1 AND body_md = old_md;
END $guide$;

