<ul><li><a href="/community/guide-placeholder/first-board" rel="ugc nofollow noopener">Primeiros passos: seu primeiro tabuleiro</a></li><li><a href="/community/guide-placeholder/specials-and-stars" rel="ugc nofollow noopener">Peças especiais, objetivos e estrelas</a></li><li><a href="/community/guide-placeholder/journey" rel="ugc nofollow noopener">Como se orientar na Jornada</a></li><li><a href="/community/guide-placeholder/voiceover" rel="ugc nofollow noopener">Jogue com o VoiceOver</a></li><li><a href="/community/guide-placeholder/settings" rel="ugc nofollow noopener">Acessibilidade e ajustes confortáveis</a></li><li><a href="/community/guide-placeholder/lives-moves-undos" rel="ugc nofollow noopener">Vidas, movimentos, desfazer e vídeos opcionais</a></li><li><a href="/community/guide-placeholder/versions" rel="ugc nofollow noopener">Qual versão do jogo estou usando?</a></li></ul>';
BEGIN
 SELECT thread_id INTO tid FROM player_guides WHERE locale = 'pt-BR' AND key = 'asking-for-help';
 IF tid IS NULL THEN RETURN; END IF;
 FOR target IN SELECT g.key, t.id, t.slug FROM player_guides g JOIN threads t ON t.id = g.thread_id WHERE g.locale = 'pt-BR' LOOP
  old_md := replace(old_md, '/community/guide-placeholder/' || target.key, '/pt-BR/community/t/' || target.id || '/' || target.slug);
  new_md := replace(new_md, '/community/guide-placeholder/' || target.key, '/pt-BR/community/t/' || target.id || '/' || target.slug);
  new_html := replace(new_html, '/community/guide-placeholder/' || target.key, '/pt-BR/community/t/' || target.id || '/' || target.slug);
 END LOOP;
 UPDATE posts SET body_md = new_md, body_html = new_html WHERE thread_id = tid AND number = 1 AND body_md = old_md;
END $guide$;

